+  void it('names the target after the targetName option', async () => {
+    const results = await infer([PROJECT, TSCONFIG], [PROJECT], {
+      targetName: 'oxlint',
+    });
+    assert.deepEqual(Object.keys(results[0][1]['libs/utils/a'].targets), [
+      'oxlint',
+    ]);
+  });
